  m.insertAdjacentHTML('afterend', "<div class=\"ffl\" id=\"ffl\">\n  <section class=\"hero rty\" id=\"top\">\n    <div class=\"wrap\">\n      <img class=\"hero__logo\" src=\"https://assets.cdn.filesafe.space/yclxxS7PDfN2MuEopX1v/media/8363b3f9-a8e9-4012-afd1-0f8b2de1b9c7.png\" alt=\"FTL Flag Football\">\n      <p class=\"eyebrow\">Registration not complete</p>\n      <h1>Wait, your registration isn&#x27;t <span>complete yet</span><span id=\"ty-first\" hidden></span></h1>\n      <p class=\"rty__sub\">Follow the steps below.</p>\n    </div>\n  </section>\n  <section class=\"sec sec--alt rty__steps\" id=\"steps\">\n    <div class=\"wrap\">\n      <div class=\"rty__step\" id=\"ty-step-1\">\n        <div class=\"rty__img rty__img--graphic\" style=\"background:#0D1B45\"><img src=\"https://files.leadconnectorhq.com/file/6b072dae7f4b143c88b650cb/soccer-juniors-winter27-ty-playmetrics.jpg\" alt=\"\" loading=\"lazy\"></div>\n        <div class=\"rty__txt\">\n        <span class=\"rty__num\">Step 1</span>\n        <h2>Create your PlayMetrics account and sign the waiver</h2>\n        <p>Your child&#x27;s spot is saved only once you finish this. Without a signed waiver your child will not be allowed to take part in the clinic.</p>\n        <ul class=\"checks\"><li><span>Create your free PlayMetrics account (already have one? Just log in)</span></li><li><span>Register your child for the FTL Flag Free Clinic \u00b7 Margate (free, nothing to pay)</span></li><li><span>Sign the waiver online</span></li></ul>\n        <div class=\"rty__btns\"><a class=\"btn btn--cta\" id=\"ty-pay\" href=\"https://app.playmetrics.com/signup?clubToken=TG9naW4tQ2x1Yi52MS0xMDgzLTE4MDA3NDE5MzJ8NmQ5STZZVlhxVkZNa0FFRnpTcVJpSXFsTGdoYU0xL2NCR0t1VDhacHhUdz0=&amp;program_id=132236&amp;attribution_id=1618\">Create account &amp; sign waiver \u2192</a><a class=\"tl__help\" href=\"https://help.playmetrics.com/hc/en-us/articles/360047807813-How-to-Register-for-a-Program-As-a-Parent\" target=\"_blank\" rel=\"noopener\">New to PlayMetrics? Here&#x27;s how to create your account \u2192</a></div>\n        </div>\n      </div>\n      <div class=\"rty__step\" id=\"ty-step-share\">\n        <div class=\"rty__img rty__img--art\" aria-hidden=\"true\"><div class=\"tyg\"><div class=\"tyg__chat\"><div class=\"tyg__bubble\">Want to come to the free FTL Flag clinic in Margate with us? Sat, Dec 5</div><div class=\"tyg__preview\"><div class=\"tyg__pvimg\"><img src=\"https://assets.cdn.filesafe.space/yclxxS7PDfN2MuEopX1v/media/8363b3f9-a8e9-4012-afd1-0f8b2de1b9c7.png\" alt=\"\"></div><div class=\"tyg__pvtxt\"><strong>FTL Flag Free Clinic \u00b7 Margate</strong><span>go.ftlflag.com/flag-clinic-margate-2026-12-web</span></div></div><div class=\"tyg__copied\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg>Link copied</div></div></div></div>\n        <div class=\"rty__txt\">\n        <span class=\"rty__num\">Step 2</span>\n        <h2>Share it with your friends</h2>\n        <p>Know a family who would love this? Send them the link so they can sign up and play with you.</p>\n        \n        <div class=\"rty__btns\"><button type=\"button\" class=\"btn btn--cta\" id=\"ty-share\" data-url=\"https://go.ftlflag.com/flag-clinic-margate-2026-12-web?utm_source=referral&amp;utm_medium=share&amp;utm_campaign=flag-clinic-margate-2026-12\">Copy the share link</button></div>\n        </div>\n      </div>\n      <div class=\"rty__step\" id=\"ty-step-cal\">\n        <div class=\"rty__img rty__img--art\" aria-hidden=\"true\"><div class=\"tyg\"><div class=\"tyg__cal\"><div class=\"tyg__date\"><span>DEC</span><strong>5</strong><span>SAT</span></div><div class=\"tyg__ev\"><strong>FTL Flag Free Clinic \u00b7 Margate</strong><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3 2\"/></svg>3:30 PM \u2013 5:30 PM</p><p><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 21s-7-6.2-7-11.5A7 7 0 0 1 19 9.5C19 14.8 12 21 12 21z\"/><circle cx=\"12\" cy=\"9.5\" r=\"2.5\"/></svg>Margate Sports Complex</p></div></div><div class=\"tyg__chip\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 16V11a6 6 0 0 1 12 0v5l2 2H4z\"/><path d=\"M10 20a2 2 0 0 0 4 0\"/></svg>Reminder: the day before</div></div></div>\n        <div class=\"rty__txt\">\n        <span class=\"rty__num\">Step 3</span>\n        <h2>Add it to your calendar</h2>\n        <p>You get a reminder before clinic day and the address is saved in the event, so directions are one tap away.</p>\n        \n        <div class=\"rty__btns\"><a class=\"btn btn--cta\" id=\"ty-gcal\" href=\"#\" target=\"_blank\" rel=\"noopener\">Add to Google Calendar</a><a class=\"btn btn--ghost\" id=\"ty-ics\" href=\"#\" download=\"flag-clinic-margate-2026-12.ics\">Apple / Outlook calendar</a></div>\n        </div>\n      </div>\n      <div class=\"rty__step\" id=\"ty-step-social\">\n        <div class=\"rty__img rty__img--art\" aria-hidden=\"true\"><div class=\"tyg\"><div class=\"tyg__prof\"><div class=\"tyg__ptop\"><div class=\"tyg__av\"><img src=\"https://assets.cdn.filesafe.space/yclxxS7PDfN2MuEopX1v/media/8363b3f9-a8e9-4012-afd1-0f8b2de1b9c7.png\" alt=\"\"></div><div class=\"tyg__pname\"><strong>@ftlutdflagfootball</strong><span>FTL Flag Football</span></div><span class=\"tyg__net\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/><circle cx=\"17.5\" cy=\"6.5\" r=\"1\" fill=\"currentColor\"/></svg></span></div><div class=\"tyg__follow\">Follow</div><div class=\"tyg__grid\"><i class=\"tyg__t0\"></i><i class=\"tyg__t1\"></i><i class=\"tyg__t2\"></i><i class=\"tyg__t0\"></i><i class=\"tyg__t1\"></i><i class=\"tyg__t2\"></i></div></div></div></div>\n        <div class=\"rty__txt\">\n        <span class=\"rty__num\">Step 4</span>\n        <h2>Follow us on social media</h2>\n        <p>Photos and highlights from the clinic, plus news about the next season.</p>\n        \n        <div class=\"rty__btns\"><a class=\"btn btn--cta\" href=\"https://www.instagram.com/ftlutdflagfootball/\" target=\"_blank\" rel=\"noopener\">Instagram \u00b7 @ftlutdflagfootball</a></div>\n        </div>\n      </div>\n    </div>\n  </section>\n  \n  <section class=\"sec sec--navy cta\" id=\"next\">\n    <div class=\"wrap\">\n      <p class=\"eyebrow\">After the clinic</p>\n      <h2>Loved it? Keep playing <span>this spring</span></h2>\n      <p class=\"lead\">FTL Flag Youth Co-Ed Rec runs February 8 to April 15, 2027 at NSU in Davie: one practice and one game a week, and every child plays in every game.</p>\n      <a class=\"btn btn--cta\" href=\"https://ftlflag.com\" target=\"_blank\" rel=\"noopener\">See the spring season \u2192</a>\n      \n    </div>\n  </section>\n</div>");
